% Solver generated by SolverMapp
clear; clc;

%% Stage 0: Inputs and start values of state variables
M          = 3; % [Input] (1) Number of species
K          = [-2, 0, 0; 1.5, -1, 0.5; 0.5, 1, -0.5]; % [Input] (1/s) Rate matrix (columns sum to 0)
c          = [1; 0; 0]; % [State] (mol/m^3) Concentrations

%% Stage 1
% --- ODE system: c over t: RK4, 200 steps ---
% Species balance: \frac{dc_i}{dt} = \sum_j K_{ij} c_j
t = 0;
h_rk = (2 - t) / 200;
w_rk = [1, 2, 2, 1]; c_rk = [0.5, 0.5, 1];
for step = 1:200
    t_rk0 = t;
    c_rk0 = c; c_acc = 0;
    for stage = 1:4
        c_rate = zeros(size(c));
        for i = 1:M
            s_sum1 = 0;
            for j = 1:M
                s_sum1 = s_sum1 + (K(i, j) * c(j));
            end
            c_rate(i) = s_sum1;
        end
        c_acc = c_acc + w_rk(stage) * c_rate;
        if stage < 4
            t = t_rk0 + c_rk(stage) * h_rk;
            c = c_rk0 + c_rk(stage) * h_rk * c_rate;
        end
    end
    t = t_rk0 + h_rk;
    c = c_rk0 + h_rk / 6 * c_acc;
end

%% Stage 2
% [EXPLICIT] Total: c_{tot} = \sum_i c_i
s_sum2 = 0;
for i = 1:M
    s_sum2 = s_sum2 + (c(i));
end
c_tot = s_sum2;

%% Results
fprintf('%-12s = %s\n', 'K', mat2str(K));
fprintf('%-12s = %s\n', 'c', mat2str(c));
fprintf('%-12s = %s\n', 't', mat2str(t));
fprintf('%-12s = %s\n', 'c_tot', mat2str(c_tot));
fprintf('%-12s = %s\n', 'M', mat2str(M));